        let t = match *n {
            "Tint" | "SubColor" => UniformType::Float4,
            "LightDir" | "CamPos" => UniformType::Float3,
            _ => UniformType::Float1,
        };
        UniformDesc::new(n, t)
    })
    .collect();
    load_material(
        ShaderSource::Glsl { vertex: VS, fragment: FS },
        MaterialParams {
            pipeline_params: PipelineParams {
                depth_test: Comparison::Always,
                depth_write: false,
                color_blend: Some(BlendState::new(Equation::Add, BlendFactor::One, BlendFactor::One)),
                ..Default::default()
            },
            uniforms,
            textures: vec!["NormalMap".to_string()],
        },
    )
    .map_err(|e| format!("{:?}", e))
}

